    let derivativeWidth = max(derivative_width, 0.35);
    let transition = clamp(transition_px, 0.35, 0.8);
    let edgeWidth = max(derivativeWidth * 0.75, transition);
    return 1.0 - smoothstep(0.0, edgeWidth, distance_px);
